import { Link, Outlet } from 'react-router-dom';

function Pagina2() {
  const layoutStyle = {
    display: 'flex',
    height: '90vh', // Make it take up most of the screen height
  };

  const navStyle = {
    borderRight: '2px solid #ccc',
    padding: '20px',
    width: '200px',
    background: '#f4f4f4',
  };

  const contentStyle = {
    padding: '20px',
    flex: 1, // Takes up the remaining space
  };

  return (
    <div style={layoutStyle}>
      {/* 1. The Permanent Side Menu */}
      <nav style={navStyle}>
        <h3>User Menu</h3>
        <ul>
          <li>
            <Link to="/about/profile">My Profile</Link>
          </li>
          <li>
            <Link to="/about/dashboard">Dashboard</Link>
          </li>
        </ul>
      </nav>

      {/* 2. The Changing Content Area */}
      <main style={contentStyle}>
        <Outlet />
      </main>
    </div>
  );
}

export default Pagina2;
